// [vite-esm] imports auto-generated by the 2026-07 Vite migration.
import "../state.js";

/**
 * Week / Term view filter for the editor grid (Wave 3b, lane W3b-7).
 *
 * Every lesson carries a week pattern and a term pattern (lesson.weeksDefId /
 * lesson.termsDefId; the definitions live in school.weeksDefs / termsDefs and
 * are the same ids the Lessons table has shown as "Week" / "Term" since Wave 1).
 * The grid drew every lesson regardless, so a school on an A/B week cycle or a
 * two-term year could not look at one week or one term in isolation.
 *
 * This module adds that view: a Week filter and a Term filter on the editor.
 *
 * Decisions
 * ---------
 * · HIDDEN, not dimmed. A filtered grid is read as "this is what Week A looks
 *   like" — a dimmed card still occupies its period, still reads as a card in
 *   that cell, and cannot be told apart from a card that is simply not this
 *   week's. What is hidden is reported by COUNT (toolbar title, panel summary,
 *   the overview stats bar and the unplaced chip's tooltip) so nothing vanishes
 *   silently.
 * · VIEW STATE ONLY. The filter lives on APP.editor (weekFilter / termFilter),
 *   never on the school, never on a card: it cannot change what is timetabled
 *   and ⌘Z is unaffected by it. Saved views capture it (js/ui/components/
 *   saved_views.js), which is how a planner keeps a "Week B" perspective.
 * · FAIL OPEN. A missing id, a definition that no longer exists or an
 *   unreadable bitmask shows the card rather than hiding work the planner
 *   cannot then find. Only a definite, readable "this lesson is not in that
 *   week/term" hides anything.
 * · The unplaced tray, the unplaced counts and the class rail follow the filter
 *   (that is what "what does Week A look like" means for work still to place).
 */

const doc = typeof document !== "undefined" ? document : null;
const win = typeof window !== "undefined" ? window : globalThis;

export const ALL = "all";

const BTN_ID = "editor-view-filter";
const PANEL_CLASS = "chrx-view-filter-panel";

const AXES = {
  week: {
    defsKeys: ["weeksDefs", "weeks"],
    bitsKeys: ["bits", "weeks"],
    lessonKey: "weeksDefId",
    allLabel: "All weeks",
  },
  term: {
    defsKeys: ["termsDefs", "terms"],
    bitsKeys: ["bits", "terms"],
    lessonKey: "termsDefId",
    allLabel: "All terms",
  },
};

function asArray(value) {
  return Array.isArray(value) ? value : [];
}

function indexById(list) {
  const out = Object.create(null);
  for (const item of asArray(list)) {
    if (item && item.id) out[item.id] = item;
  }
  return out;
}

/** Every week (or term) definition the school has, de-duplicated by id. */
export function defsFor(school, axis) {
  const meta = AXES[axis];
  if (!meta || !school) return [];
  const out = [];
  const seen = Object.create(null);
  for (const key of meta.defsKeys) {
    for (const def of asArray(school[key])) {
      if (!def || !def.id || seen[def.id]) continue;
      seen[def.id] = 1;
      out.push(def);
    }
  }
  return out;
}

/**
 * The bitmask string of a definition. The XML parser stores it in `bits`
 * (<weeksdef weeks="10">), the entity dialogs in `weeks` / `terms`
 * (see js/xml/parse_timetable_xml.js and js/ui/entities/weeks.js).
 */
export function bitsOf(def, axis) {
  const meta = AXES[axis];
  if (!meta || !def) return "";
  for (const key of meta.bitsKeys) {
    const bits = def[key];
    if (bits !== undefined && bits !== null && String(bits) !== "") return String(bits);
  }
  return "";
}

/** "1", "11", "111111" — a pattern that is on in every week/term it knows about. */
function isAllBits(bits) {
  const b = String(bits || "");
  return b.length > 0 && /^1+$/.test(b);
}

/**
 * A definition that restricts nothing: "All weeks" / "Whole year" / every bit
 * set. Mirrors the isDefaultPattern rules in js/ui/entities/lessons.js so the
 * filter and the Lessons table's Week/Term columns agree on which patterns mean
 * "runs all year".
 */
export function isAllDef(def, axis) {
  if (!def) return true;
  const name = String(def.name || "").toLowerCase().trim();
  const short = String(def.short || "").toLowerCase().trim();
  if (name === "all" || short === "all" || name === "default") return true;
  if (axis === "term" && (name === "whole year" || name === "all terms" || short === "yr")) return true;
  if (axis === "week" && (name === "all weeks" || name === "every week")) return true;
  return isAllBits(bitsOf(def, axis));
}

/** The definitions a user can actually filter by ("All weeks" is the default option). */
export function restrictiveDefs(school, axis) {
  return defsFor(school, axis).filter((def) => !isAllDef(def, axis));
}

export function defLabel(def) {
  if (!def) return "";
  return String(def.name || def.short || def.id || "");
}

/**
 * Filter state from anything carrying the two fields: APP.editor, a saved view,
 * or an already-normalized `{ week, term }` (idempotent, so callers never have
 * to remember which shape they hold).
 */
export function normalizeFilter(raw) {
  const out = { week: ALL, term: ALL };
  if (!raw) return out;
  const week = raw.weekFilter || raw.week;
  const term = raw.termFilter || raw.term;
  if (typeof week === "string" && week) out.week = week;
  if (typeof term === "string" && term) out.term = term;
  return out;
}

function axisMatches(lesson, filterId, school, axis) {
  const meta = AXES[axis];
  if (!meta) return true;
  if (!filterId || filterId === ALL) return true;            // no restriction
  const byId = indexById(defsFor(school, axis));
  const target = byId[filterId];
  if (!target) return true;                                  // unknown filter → fail open
  if (isAllDef(target, axis)) return true;                   // filtered BY "All weeks"
  const lessonDefId = lesson ? lesson[meta.lessonKey] : null;
  if (!lessonDefId) return true;                             // lesson runs all year
  const lessonDef = byId[lessonDefId];
  if (!lessonDef) return true;                               // definition vanished → fail open
  if (isAllDef(lessonDef, axis)) return true;                // lesson runs all year
  const want = bitsOf(target, axis);
  const have = bitsOf(lessonDef, axis);
  if (!want || !have) return true;                           // unreadable bitmask → fail open
  const n = Math.min(want.length, have.length);
  for (let i = 0; i < n; i++) if (want[i] === "1" && have[i] === "1") return true;
  return false;
}

/** Does this lesson run in the week and term the filter selects? */
export function lessonMatchesFilter(lesson, filter, school) {
  if (!lesson) return true;
  return matchesNormalized(lesson, normalizeFilter(filter), school);
}

/** Same, for a filter that has already been through normalizeFilter. */
function matchesNormalized(lesson, f, school) {
  if (!lesson) return true;
  return axisMatches(lesson, f.week, school, "week") && axisMatches(lesson, f.term, school, "term");
}

function lessonIndex(school) {
  if (school && school._idx && school._idx.lessonById) return school._idx.lessonById;
  return indexById(school && school.lessons);
}

function cardMatchesFilter(card, f, school, lessons) {
  if (!card) return true;
  const lesson = (lessons || lessonIndex(school))[card.lessonId];
  if (!lesson) return true;                                  // unrenderable anyway; not ours to hide
  return matchesNormalized(lesson, f, school);
}

/** Ids of the cards the grid may draw under this filter. */
export function visibleCardIds(school, filter) {
  if (!school) return [];
  const lessons = lessonIndex(school);
  const f = normalizeFilter(filter);
  const out = [];
  for (const card of asArray(school.cards)) {
    if (card && cardMatchesFilter(card, f, school, lessons)) out.push(card.id);
  }
  return out;
}

/** How many cards this filter takes off the grid (0 when nothing is filtered). */
export function hiddenCardCount(school, filter) {
  return countsFor(school, normalizeFilter(filter)).hidden;
}

/** How many cards the grid may draw under this filter. */
export function visibleCardCount(school, filter) {
  return countsFor(school, normalizeFilter(filter)).visible;
}

function countsFor(school, f) {
  const lessons = lessonIndex(school);
  let total = 0;
  let hidden = 0;
  for (const card of asArray(school && school.cards)) {
    if (!card || !lessons[card.lessonId]) continue;
    total++;
    if (!cardMatchesFilter(card, f, school, lessons)) hidden++;
  }
  return { total, hidden, visible: total - hidden };
}

/**
 * Everything the UI needs to describe the current filter in words:
 * the toolbar label, the panel summary and the honest "N hidden" note.
 */
export function describeFilter(school, filter) {
  const f = normalizeFilter(filter);
  const byId = {
    week: indexById(defsFor(school, "week")),
    term: indexById(defsFor(school, "term")),
  };
  const parts = [];
  const weekDef = f.week !== ALL ? byId.week[f.week] : null;
  const termDef = f.term !== ALL ? byId.term[f.term] : null;
  if (weekDef) parts.push(defLabel(weekDef));
  if (termDef) parts.push(defLabel(termDef));
  const active = parts.length > 0;
  const counts = countsFor(school, f);
  const label = active ? parts.join(" · ") : AXES.week.allLabel;
  const summary = active
    ? `Showing ${counts.visible} of ${counts.total} cards — ${counts.hidden} hidden (${label}).`
    : `Showing all ${counts.total} cards.`;
  const title = active
    ? `Week & term filter: ${label} — ${counts.hidden} of ${counts.total} cards hidden. Click to change.`
    : "Week & term filter: showing all weeks and all terms. Click to filter the grid by week or term.";
  return {
    active,
    week: f.week,
    term: f.term,
    weekLabel: weekDef ? defLabel(weekDef) : AXES.week.allLabel,
    termLabel: termDef ? defLabel(termDef) : AXES.term.allLabel,
    label,
    summary,
    title,
    total: counts.total,
    visible: counts.visible,
    hidden: counts.hidden,
  };
}

/* ─────────────────────────── browser wiring ─────────────────────────── */

function editorState() {
  const APP = (win.APP = win.APP || {});
  return (APP.editor = APP.editor || {});
}

function school() {
  return (win.APP && win.APP.school) || null;
}

/** The editor's live filter ({ week, term }). */
export function currentFilter() {
  return normalizeFilter(editorState());
}

function setAxis(axis, value) {
  const ed = editorState();
  const key = axis === "week" ? "weekFilter" : "termFilter";
  const next = value && value !== ALL ? String(value) : ALL;
  if (ed[key] === next) return;
  ed[key] = next;
  syncButton();
  renderPanel();
  rerenderEditor();
}

function clear() {
  const ed = editorState();
  ed.weekFilter = ALL;
  ed.termFilter = ALL;
  syncButton();
  renderPanel();
  rerenderEditor();
}

/**
 * Restore the filter captured by a saved view. Deliberately does NOT re-render:
 * the caller (SavedViews.apply) already re-renders the editor.
 */
function setFromView(view) {
  const ed = editorState();
  const f = normalizeFilter(view);
  ed.weekFilter = f.week;
  ed.termFilter = f.term;
  syncButton();
  renderPanel();
}

function rerenderEditor() {
  if (win.EditorActivator && typeof win.EditorActivator.activate === "function") {
    win.EditorActivator.activate();
    return;
  }
  const host = doc && (doc.getElementById("editor-root") || doc.querySelector(".chrx-editor"));
  if (host && win.Editor && typeof win.Editor.render === "function") {
    try { win.Editor.render(host); } catch (_e) {}
  }
}

function syncButton() {
  if (!doc) return;
  const btn = doc.getElementById(BTN_ID);
  if (!btn) return;
  const d = describeFilter(school(), currentFilter());
  const label = btn.querySelector(".chrx-tool__label");
  if (label) label.textContent = d.label;
  else btn.textContent = d.label;
  btn.title = d.title;
  btn.classList.toggle("is-on", d.active);
  btn.setAttribute("aria-pressed", d.active ? "true" : "false");
}

let panelEl = null;

function closePanel() {
  if (!panelEl) return;
  panelEl.remove();
  panelEl = null;
  const btn = doc && doc.getElementById(BTN_ID);
  if (btn) btn.setAttribute("aria-expanded", "false");
}

function optionHtml(id, text, selected) {
  return `<option value="${id}"${selected ? " selected" : ""}>${text}</option>`;
}

function selectHtml(axis, current) {
  const meta = AXES[axis];
  const defs = restrictiveDefs(school(), axis);
  const options = [optionHtml(ALL, meta.allLabel, current === ALL)]
    .concat(defs.map((def) => optionHtml(def.id, defLabel(def), current === def.id)));
  return `<select id="chrx-vf-${axis}" class="mt-0.5 w-full border border-slate-300 rounded px-2 py-1 text-xs bg-white">${options.join("")}</select>`;
}

/** Rebuild the popover body (options can change while it is open — entities, undo). */
function renderPanel() {
  if (!panelEl) return;
  const d = describeFilter(school(), currentFilter());
  const body = panelEl.querySelector(".chrx-view-filter__body");
  if (!body) return;
  const anyPatterns = restrictiveDefs(school(), "week").length || restrictiveDefs(school(), "term").length;
  body.innerHTML = `
    <label class="block mb-2"><span class="text-xs text-slate-500">Weeks</span>${selectHtml("week", d.week)}</label>
    <label class="block mb-2"><span class="text-xs text-slate-500">Terms</span>${selectHtml("term", d.term)}</label>
    <p id="chrx-vf-summary" class="text-xs text-slate-500 m-0 mb-2" aria-live="polite">${d.summary}</p>
    ${anyPatterns ? "" : `<p id="chrx-vf-hint" class="text-xs text-slate-400 m-0 mb-2">This timetable defines only "All weeks" / "Whole year". Add week or term patterns in the ribbon's Weeks / Terms lists to scope lessons.</p>`}
    <div class="flex items-center justify-between gap-2">
      <button type="button" id="chrx-vf-reset" class="px-2 py-1 border border-slate-300 rounded text-xs text-slate-700 hover:bg-slate-50">Show all weeks &amp; terms</button>
      <button type="button" id="chrx-vf-done" class="px-2 py-1 bg-blue-600 text-white rounded text-xs">Done</button>
    </div>
  `;
  body.querySelector("#chrx-vf-week").onchange = (e) => setAxis("week", e.target.value);
  body.querySelector("#chrx-vf-term").onchange = (e) => setAxis("term", e.target.value);
  body.querySelector("#chrx-vf-reset").onclick = () => clear();
  body.querySelector("#chrx-vf-done").onclick = () => closePanel();
}

function openPanel() {
  if (!doc) return;
  const btn = doc.getElementById(BTN_ID);
  if (!btn) return;
  closePanel();
  panelEl = doc.createElement("div");
  panelEl.className = `${PANEL_CLASS} fixed z-50 rounded-xl border border-slate-200 bg-white p-3 shadow-2xl text-sm`;
  panelEl.setAttribute("role", "dialog");
  panelEl.setAttribute("aria-label", "Week and term filter");
  panelEl.style.width = "300px";
  panelEl.innerHTML = `
    <div class="flex items-center justify-between mb-2">
      <span class="font-semibold text-slate-800">Week &amp; term filter</span>
      <button type="button" id="chrx-vf-close" class="text-slate-400 hover:text-slate-600 font-bold px-1" aria-label="Close filter">✕</button>
    </div>
    <div class="chrx-view-filter__body"></div>
  `;
  doc.body.appendChild(panelEl);
  const rect = btn.getBoundingClientRect();
  const width = 300;
  const left = Math.max(8, Math.min(rect.left, (win.innerWidth || 1024) - width - 8));
  panelEl.style.top = `${Math.round(rect.bottom + 6)}px`;
  panelEl.style.left = `${Math.round(left)}px`;
  panelEl.querySelector("#chrx-vf-close").onclick = () => closePanel();
  btn.setAttribute("aria-expanded", "true");
  renderPanel();
}

function togglePanel() {
  if (panelEl) closePanel();
  else openPanel();
}

if (doc) {
  doc.addEventListener("click", (e) => {
    const target = e.target;
    if (!target || typeof target.closest !== "function") return;
    if (target.closest(`#${BTN_ID}`)) {
      e.preventDefault();
      togglePanel();
      return;
    }
    if (panelEl && !panelEl.contains(target)) closePanel();
  });
  // Escape is handled by the shell's one key handler (js/ui/shell_v3.js), which
  // closes this panel first — see the `.chrx-view-filter-panel` branch there.
  // Registering a second Escape handler here would run after it and exit
  // fullscreen underneath the panel.
  // The toolbar label must survive a school swap and a step change, and the
  // panel's option lists must not go stale behind an undo (entity dialogs add
  // and delete patterns). Both are cheap re-reads, not listeners on data.
  for (const evt of ["app:school-loaded", "step:changed", "entity:changed", "app:school-changed"]) {
    doc.addEventListener(evt, () => {
      syncButton();
      renderPanel();
    });
  }
  if (doc.readyState === "loading") doc.addEventListener("DOMContentLoaded", syncButton);
  else syncButton();
}

/* ────────────────────── test hooks (e2e only) ──────────────────────
 * Writing school data from a test goes through APP.mutate like every other
 * write in the app, so the fixtures are undoable and cannot corrupt the model
 * in a way the app itself could not. Used by e2e/w3b-7-week-term-filter.spec.js.
 */
function mutate(label, fn) {
  const APP = win.APP;
  if (APP && typeof APP.mutate === "function") return APP.mutate(label, fn);
  if (APP && APP.school) return fn(APP.school);
  return null;
}

function addDef(axis, name, bits) {
  const key = axis === "week" ? "weeksDefs" : "termsDefs";
  const id = "vf_" + axis + "_" + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
  mutate(`Add ${axis} pattern`, (s) => {
    s[key] = Array.isArray(s[key]) ? s[key] : [];
    s[key].push({ id, name, short: name, bits });
  });
  rerenderEditor();
  return id;
}

function testHooks() {
  return {
    seedPatterns() {
      const weekA = addDef("week", "Week A", "10");
      const weekB = addDef("week", "Week B", "01");
      const term1 = addDef("term", "Term 1", "10");
      const term2 = addDef("term", "Term 2", "01");
      syncButton();
      return { weekA, weekB, term1, term2 };
    },
    restrictLesson(lessonId, fields) {
      mutate("Restrict lesson", (s) => {
        const lesson = (s.lessons || []).find((l) => l.id === lessonId);
        if (lesson) Object.assign(lesson, fields || {});
      });
      rerenderEditor();
      return lessonId;
    },
    /** A lesson with no cards, so the unplaced tray has something to filter. */
    addUnplacedLesson(fields) {
      const s = school() || {};
      const src = (s.lessons || [])[0] || {};
      const id = "vf_lesson_" + Date.now().toString(36);
      mutate("Add unplaced lesson", (sc) => {
        sc.lessons = Array.isArray(sc.lessons) ? sc.lessons : [];
        sc.lessons.push({
          id,
          classIds: (src.classIds || []).slice(0, 1),
          teacherIds: (src.teacherIds || []).slice(0, 1),
          subjectId: src.subjectId,
          periodsPerWeek: 1,
          periodsPerCard: 1,
          lessonLength: 1,
          termsDefId: src.termsDefId,
          ...(fields || {}),
        });
      });
      rerenderEditor();
      return id;
    },
    state() {
      const d = describeFilter(school(), currentFilter());
      return { week: d.week, term: d.term, label: d.label, hidden: d.hidden, total: d.total };
    },
  };
}

win.ViewFilter = {
  ALL,
  // pure API
  defsFor,
  bitsOf,
  isAllDef,
  restrictiveDefs,
  defLabel,
  normalizeFilter,
  lessonMatchesFilter,
  visibleCardIds,
  hiddenCardCount,
  visibleCardCount,
  describeFilter,
  // editor API
  currentFilter,
  setAxis,
  clear,
  setFromView,
  syncButton,
  openPanel,
  closePanel,
  togglePanel,
  __test: testHooks(),
};

export const ViewFilter = win.ViewFilter;
